package com.bananalab.lite;
import android.content.*;import android.app.*;import android.os.*;
final class ReadingBudget implements ReadingWeights.Governor{
 static final class Paused extends Exception{Paused(String reason){super(reason);}}
 final Context context;final long deadline;final boolean background;long checked;ReadingBudget(Context c,int seconds){this(c,seconds,false);}ReadingBudget(Context c,int seconds,boolean bg){context=c;background=bg;deadline=System.nanoTime()+seconds*1000000000L;}
 static String reason(long free,int thermal,int temperature,boolean low){if(low||free<33554432L)return "memoria disponible insuficiente";if(thermal>=3||temperature>=430)return "temperatura elevada";return "";}
 public void check()throws Exception{if(background&&(!LearningLoop.enabled(context)||LearningLoop.busy))throw new Paused("aprendizaje pausado o chat trabajando");if(Thread.currentThread().isInterrupted())throw new Paused("sesión cancelada");if(System.nanoTime()>deadline)throw new Paused("límite de tiempo de la tanda");long now=System.nanoTime();if(now-checked<250000000L)return;checked=now;if(background)LearningLoop.check(context);Runtime runtime=Runtime.getRuntime();long free=runtime.maxMemory()-(runtime.totalMemory()-runtime.freeMemory());boolean low=false;ActivityManager manager=(ActivityManager)context.getSystemService(Context.ACTIVITY_SERVICE);if(manager!=null){ActivityManager.MemoryInfo info=new ActivityManager.MemoryInfo();manager.getMemoryInfo(info);low=info.lowMemory;}int thermal=0,temp=-1;if(Build.VERSION.SDK_INT>=29)try{Object power=context.getSystemService(Context.POWER_SERVICE);thermal=((Integer)power.getClass().getMethod("getCurrentThermalStatus").invoke(power)).intValue();}catch(Exception unavailable){}try{Intent battery=context.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null)temp=battery.getIntExtra("temperature",-1);}catch(Exception unavailable){}String reason=reason(free,thermal,temp,low);if(!reason.isEmpty())throw new Paused(reason);}
}
